if not value or not value.get('assetId') or not value.get('performanceEventId'): return {}
rows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.event.getPerformanceEvents({'assetId': value['assetId']}))
match = [r for r in rows if r['performanceEventId'] == value['performanceEventId']]
return match[0] if match else {}

#A reason the system chose isn't preselected: the operator picks the real one
if not value: return {'reason': None, 'reasonPath': None, 'note': ''}
auto = value.get('autoReason')
return {'reason': None if auto else value.get('performanceStateId'), 'reasonPath': None if auto else value.get('performanceStatePath') or value.get('performanceStateName'), 'note': value.get('note') or ''}

#The reason a person set on the event, so the tree selects it (the system's reason isn't preselected)
if not value or value.get('autoReason'): return None
return value.get('performanceStatePath')

#Performance reasons are linked to an asset or one above it (a site, area or line), and to items
headers = ['performanceStateId', 'performanceStateName', 'performanceStatePath', 'iconPath', 'iconColor']
#None until the event has loaded, and props.path is empty until then (in props too), so the tree starts once, with the reasons.
#Started earlier, the path flicked to empty and back and the tree could keep an instance that never got them: blank on first open
if value is None: return None
if not value: return system.dataset.toDataSet(headers, [])
paramsDict = {}
if value.get('itemId'): paramsDict['itemPath'] = system.kanoa.utilities.getFieldValue('itemPath', system.kanoa.item.getItems({'itemId': value['itemId']}))
if value.get('assetPath'): paramsDict['assetPath'] = value['assetPath']
rows, seen = [], set()
for row in system.kanoa.utilities.convertDatasetToJSON(system.kanoa.performanceState.getAssetPerformanceStates(paramsDict)):
	if row['performanceStateId'] in seen: continue
	seen.add(row['performanceStateId'])
	rows.append([row['performanceStateId'], row['performanceStateName'], row['performanceStatePath'], 'material/speed', row.get('performanceStateColor')])
return system.dataset.toDataSet(headers, rows)
